        if c != 1:
            sys.exit(f"⚠️ {f} の {i+1} 番目の印が {c} 回。何も書いていない（もう当ててあるか、43a・43m がまだ）\n--- 探した行 ---\n{old}")
        s = s.replace(old, new)
